import numpy as np

def example_cost(output, label):
    target = np.zeros(10)
    target[label] = 1.0           # 정답 칸만 1
    return np.sum((output - target) ** 2)

def average_cost(outputs, labels):
    # outputs: (그림 수, 10), labels: (그림 수,)
    return np.mean([example_cost(o, l) for o, l in zip(outputs, labels)])

rng = np.random.default_rng(0)
random_outputs = rng.random((1000, 10))   # 학습 전 신경망처럼 엉망인 출력
labels = rng.integers(0, 10, size=1000)
print(round(average_cost(random_outputs, labels), 2))  # 대략 3 안팎
